package com.muthumol.player.dummy;
import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.zip.*;import java.util.regex.*;import org.json.*;import org.drinkless.tdlib.TdApi;
/** Bounded subtitle matching with manual-choice precedence and per-selection cancellation. */
final class AutoSubtitles {
 final ChannelSession session;final ExecutorService worker=Executors.newSingleThreadExecutor();volatile int generation;String selected="";
 AutoSubtitles(ChannelSession s){session=s;}
 static boolean subtitle(String n){return n.toLowerCase(Locale.ROOT).matches(".*\\.(srt|ass|ssa|vtt|ttml)$");}
 static MediaTitle title(String name){return MediaTitle.parse(name.replaceFirst("(?i)\\.(srt|ass|ssa|vtt|ttml|zip)$","").replaceAll("(?i)\\b(malayalam|mal|eng|subtitles?|msone)\\b"," "));}
 static int releaseScore(String video,String subtitle){int score=0;String v=video.toLowerCase(Locale.ROOT).replaceAll("[._]"," "),s=subtitle.toLowerCase(Locale.ROOT).replaceAll("[._]"," ");for(String family:new String[]{"web[ -]?dl|webrip","blu[ -]?ray|brrip","hdtv","dvdrip"}){Pattern p=Pattern.compile("\\b(?:"+family+")\\b");if(p.matcher(v).find()&&p.matcher(s).find())score+=30;}for(String tag:new String[]{"2160p","1080p","720p","480p","proper","repack"})if(v.contains(tag)&&s.contains(tag))score+=5;return score;}
 static int score(Movie movie,String name,String caption){MediaTitle w=MediaTitle.parse(movie.title),f=title(name);if(f.episodic()&&(!w.episodic()||w.season!=f.season||w.episode!=f.episode))return -1;if(w.year>0&&f.year>0&&w.year!=f.year)return -1;MediaTitle c=f;if((MediaTitle.similarity(w.name,c.name)<.85||w.episodic()&&!c.episodic())&&!caption.isEmpty())c=title(caption);if(w.episodic()!=c.episodic()||w.episodic()&&(w.season!=c.season||w.episode!=c.episode)||w.year>0&&c.year>0&&w.year!=c.year)return -1;double similarity=MediaTitle.similarity(w.name,c.name);if(similarity<.85)return -1;boolean mal=Pattern.compile("(?i)\\b(malayalam|mal|ml|msone)\\b").matcher((name+" "+caption).replaceAll("[._]"," ")).find();return (int)(similarity*100)+(mal?100:0)+releaseScore(movie.title,name+" "+caption);}
 static boolean pack(Movie movie,String name){MediaTitle t=MediaTitle.parse(movie.title);if(!name.toLowerCase(Locale.ROOT).endsWith(".zip"))return false;String clean=name.replaceFirst("(?i)\\.zip$","").replaceAll("[._]"," ");Matcher season=Pattern.compile("(?i)\\b(?:s|season\\s*)(\\d{1,2})\\b").matcher(clean);if(t.episodic()){if(!season.find()||Integer.parseInt(season.group(1))!=t.season)return false;clean=clean.substring(0,season.start());}return MediaTitle.similarity(t.name,title(clean).name)>=.85;}
 static final class Candidate{final Object doc;final String name;final int score;Candidate(Object d,String n,int s){doc=d;name=n;score=s;}}
 void find(Movie movie){if(movie.chatId==0||selected.equals(movie.cacheIdentity()))return;android.content.SharedPreferences manual=session.context.getSharedPreferences("player",0);if(manual.getBoolean("externalSubtitleOff:"+movie.cacheIdentity(),false)||!manual.getString("externalSubtitleUri:"+movie.cacheIdentity(),"").isEmpty())return;selected=movie.cacheIdentity();int token=++generation;session.subtitleStatus="Searching subtitles in this chat…";worker.execute(()->run(movie,token));}
 void retry(Movie m){session.context.getSharedPreferences("auto-subtitles",0).edit().remove(MediaCache.key(m.cacheIdentity())+":name").apply();selected="";find(m);}
 void run(Movie movie,int token){try{String key=MediaCache.key(movie.cacheIdentity());android.content.SharedPreferences cache=session.context.getSharedPreferences("auto-subtitles",0);File folder=new File(session.context.getFilesDir(),"channel-subtitles");folder.mkdirs();File saved=new File(folder,key+"-auto.srt");String savedName=cache.getString(key+":name","");if(!savedName.isEmpty()&&saved.isFile()&&readable(SmallFileIO.read(saved,4*1024*1024))){publish(movie,token,saved,savedName,"Saved subtitle");return;}
  List<Candidate> list=new ArrayList<>();Set<Long> cursors=new HashSet<>();Set<Integer> files=new HashSet<>();long from=0;
  while(token==generation){TdApi.Object response=session.tg.waitRequest("SearchChatMessages","chatId",movie.chatId,"topicId",null,"query","","senderId",null,"fromMessageId",from,"offset",0,"limit",100,"filter",TelegramBridge.obj("SearchMessagesFilterDocument"));if(response instanceof TdApi.Error)throw new IOException(TelegramBridge.str(response,"message"));Object raw=TelegramBridge.get(response,"messages");if(!(raw instanceof TdApi.Message[]))throw new IOException("Subtitle search unavailable");for(TdApi.Message message:(TdApi.Message[])raw){Object doc=TelegramBridge.get(message.content,"document");String name=TelegramBridge.str(doc,"fileName");int rank=subtitle(name)?score(movie,name,TelegramBridge.str(TelegramBridge.get(message.content,"caption"),"text")):pack(movie,name)?50+releaseScore(movie.title,name):-1;int id=(int)TelegramBridge.num(TelegramBridge.get(doc,"document"),"id");if(rank>=0&&files.add(id)){list.add(new Candidate(doc,name,rank));list.sort((a,b)->Integer.compare(b.score,a.score));if(list.size()>12)list.remove(list.size()-1);}}long next=TelegramBridge.num(response,"nextFromMessageId");if(next<=0||next==from||!cursors.add(next))break;from=next;}
  if(token!=generation)return;Packed found=null;String source="Telegram chat";for(Candidate candidate:list){try{Object file=TelegramBridge.get(candidate.doc,"document");long size=TelegramBridge.num(file,"size");if(size>16*1024*1024)continue;int id=(int)TelegramBridge.num(file,"id");session.tg.download(id,0,size>0?size:16*1024*1024,8);long end=android.os.SystemClock.elapsedRealtime()+30000;while(token==generation&&android.os.SystemClock.elapsedRealtime()<end){Object fresh=session.tg.waitRequest("GetFile","fileId",id),local=TelegramBridge.get(fresh,"local");if(TelegramBridge.bool(local,"isDownloadingCompleted")){found=prepare(SmallFileIO.read(new File(TelegramBridge.str(local,"path")),16*1024*1024),movie,candidate.name);break;}TelegramRangeLoader.sleep(100);}if(found!=null)break;}catch(Exception ignored){}if(token!=generation)return;}
  if(found==null){session.subtitleStatus="Checking MSone…";MsoneSubtitles.Result result=MsoneSubtitles.find(movie,session.context);if(result!=null){found=new Packed(result.name,result.bytes);source="MSone";}}
  if(token!=generation)return;if(found==null){session.subtitleStatus="No matching subtitle found";return;}File temporary=new File(folder,key+"-"+token+".part");try{SmallFileIO.write(temporary,found.bytes);SmallFileIO.copySubtitle(temporary,saved);}finally{temporary.delete();}if(token!=generation)return;cache.edit().putString(key+":name",found.name).apply();publish(movie,token,saved,found.name,source);trim(folder,saved);
 }catch(Exception e){if(token==generation)session.subtitleStatus="Auto subtitles: "+e.getMessage();}finally{session.notifyChanged();}}
 void publish(Movie movie,int token,File file,String name,String source){session.ui.post(()->{if(token!=generation||session.movie==null||!session.movie.cacheIdentity().equals(movie.cacheIdentity()))return;session.subtitlePath=file.getAbsolutePath();session.subtitleName=name;session.subtitleType=PlayerActivity.subtitleMime(name);session.subtitleStatus=source+" · "+name;session.prefs.edit().putString("subtitlePath",session.subtitlePath).putString("subtitleName",name).putString("subtitleType",session.subtitleType).apply();session.notifyChanged();});}
 static void trim(File folder,File current){File[] files=folder.listFiles((d,n)->n.endsWith("-auto.srt"));if(files==null)return;Arrays.sort(files,Comparator.comparingLong(File::lastModified).reversed());long bytes=0;for(File f:files){bytes+=f.length();if(bytes>32*1024*1024&&!f.equals(current))f.delete();}}
 static final class Packed{final String name;final byte[] bytes;Packed(String n,byte[] b){name=n;bytes=b;}}
 static Packed prepare(byte[] bytes,Movie movie,String name)throws Exception{Packed result=name.toLowerCase(Locale.ROOT).endsWith(".zip")||bytes.length>3&&bytes[0]=='P'&&bytes[1]=='K'?unpack(bytes,movie,name):subtitle(name)?new Packed(name,bytes):null;return result!=null&&readable(result.bytes)?result:null;}
 static boolean readable(byte[] bytes){if(bytes.length==0||bytes.length>4*1024*1024)return false;java.nio.charset.Charset charset=bytes.length>1&&((bytes[0]&255)==255&&(bytes[1]&255)==254||(bytes[0]&255)==254&&(bytes[1]&255)==255)?java.nio.charset.StandardCharsets.UTF_16:java.nio.charset.StandardCharsets.UTF_8;String text=new String(bytes,charset);return !text.toLowerCase(Locale.ROOT).contains("<html")&&(text.contains("-->")||text.contains("[Events]")&&text.contains("Dialogue:")||text.contains("<tt"));}
 static boolean anonymousEpisode(String name){String clean=name.replaceFirst("(?i)\\.(srt|ass|ssa|vtt|ttml)$","").replaceAll("[._]"," ");return MediaTitle.EP.matcher(clean).replaceAll("").replaceAll("(?i)\\b(malayalam|english|eng|mal|msone|subtitles?)\\b","").trim().isEmpty();}
 static Packed unpack(byte[] archive,Movie movie,String outer)throws Exception{Packed best=null;int rank=-1,count=0,total=0;MediaTitle wanted=MediaTitle.parse(movie.title);try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(archive))){ZipEntry entry;while((entry=zip.getNextEntry())!=null){if(++count>1000)throw new IOException("Too many subtitle entries");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] block=new byte[8192];int n;while((n=zip.read(block))!=-1){total+=n;if(total>32*1024*1024||out.size()+n>4*1024*1024)throw new IOException("Subtitle pack too large");out.write(block,0,n);}if(entry.isDirectory()||!subtitle(entry.getName()))continue;String base=new File(entry.getName()).getName();int score=score(movie,base,"");MediaTitle inner=title(base);if(score<0&&pack(movie,outer)&&anonymousEpisode(base)&&wanted.episodic()&&inner.episodic()&&wanted.season==inner.season&&wanted.episode==inner.episode)score=70;if(score>rank&&readable(out.toByteArray())){rank=score;best=new Packed(base,out.toByteArray());}}}return best;}
}
